// File excluded from build by automated review.// Reason: duplicate void getElevation(); main.cpp uses OSErr getElevation in getElevation.cpp#if 0#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"void getElevation ( FSSpec theMeshFSSpec );void getElevation ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError;	unsigned char *TheMap;	int i, x, y, max, min;	long meshSize, meshWidth, meshHeight;	Myth256Palette thePalette;	meshHeader theMeshHeader;	gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsRdPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	TheMap = (unsigned char *) NewPtr (meshSize);	FileSeek ( theMeshFileRef, 1088L );	FileRead ( theGrid, theMeshHeader.meshLength, theMeshFileRef );	FSClose ( theMeshFileRef );	// make the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	// find lowest and highest elevations on the map for scaling and zeroing	max = -10000;	min = 10000;	for ( i = 0; i < meshSize; i++ ){		if (theGrid[i].height > max)			max = theGrid[i].height;		if (theGrid[i].height < min)			min = theGrid[i].height;	}	max -= min;	// get the grid Z data into an array	for ( y = 0, i = 0; y < meshHeight * meshWidth; y += meshWidth ){		for ( x = meshWidth - 1; x >= 0; x--, i++ ){			TheMap[x + y] = (theGrid[i].height -= min) / (max / 255);			// raise everything up so the low is zero and scale		}	}	writeBMP( "\p:Graphics.out:elevation.bmp", meshWidth, meshHeight, &thePalette, (char *) TheMap );	DisposePtr ( (Ptr) TheMap );	DisposePtr ( (Ptr) theGrid );}#endif